CREATE TYPE "SupplierTier" AS ENUM ('TIER_1', 'TIER_2', 'TIER_3', 'OTHER');
CREATE TYPE "Criticality" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
CREATE TYPE "TransportMode" AS ENUM ('ROAD', 'RAIL', 'SEA', 'AIR', 'MULTIMODAL', 'OTHER');

CREATE TABLE "suppliers" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "name" TEXT NOT NULL, "legal_name" TEXT, "country" TEXT NOT NULL, "city" TEXT, "latitude" DECIMAL(9,6), "longitude" DECIMAL(9,6), "supplier_type" TEXT, "tier" "SupplierTier" NOT NULL, "criticality" "Criticality" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "suppliers_pkey" PRIMARY KEY ("id"));
CREATE TABLE "factories" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "supplier_id" UUID, "name" TEXT NOT NULL, "address" TEXT, "country" TEXT NOT NULL, "city" TEXT, "latitude" DECIMAL(9,6), "longitude" DECIMAL(9,6), "production_type" TEXT, "criticality" "Criticality" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "factories_pkey" PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "name" TEXT NOT NULL, "sku" TEXT, "category" TEXT, "description" TEXT, "criticality" "Criticality" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "products_pkey" PRIMARY KEY ("id"));
CREATE TABLE "materials" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "name" TEXT NOT NULL, "category" TEXT, "commodity" TEXT, "criticality" "Criticality" NOT NULL, "substitutable" BOOLEAN NOT NULL DEFAULT false, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "materials_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ports" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "country" TEXT NOT NULL, "city" TEXT, "latitude" DECIMAL(9,6), "longitude" DECIMAL(9,6), "port_code" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "ports_pkey" PRIMARY KEY ("id"));
CREATE TABLE "routes" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "name" TEXT NOT NULL, "origin_label" TEXT NOT NULL, "destination_label" TEXT NOT NULL, "transport_mode" "TransportMode" NOT NULL, "criticality" "Criticality" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "routes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "factory_products" ("customer_id" UUID NOT NULL, "factory_id" UUID NOT NULL, "product_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "factory_products_pkey" PRIMARY KEY ("factory_id","product_id"));
CREATE TABLE "product_materials" ("customer_id" UUID NOT NULL, "product_id" UUID NOT NULL, "material_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "product_materials_pkey" PRIMARY KEY ("product_id","material_id"));
CREATE TABLE "supplier_products" ("customer_id" UUID NOT NULL, "supplier_id" UUID NOT NULL, "product_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "supplier_products_pkey" PRIMARY KEY ("supplier_id","product_id"));
CREATE TABLE "route_ports" ("customer_id" UUID NOT NULL, "route_id" UUID NOT NULL, "port_id" UUID NOT NULL, "sequence" INTEGER NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "route_ports_pkey" PRIMARY KEY ("route_id","port_id"));
CREATE TABLE "route_suppliers" ("customer_id" UUID NOT NULL, "route_id" UUID NOT NULL, "supplier_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "route_suppliers_pkey" PRIMARY KEY ("route_id","supplier_id"));
CREATE TABLE "route_factories" ("customer_id" UUID NOT NULL, "route_id" UUID NOT NULL, "factory_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "route_factories_pkey" PRIMARY KEY ("route_id","factory_id"));

CREATE UNIQUE INDEX "suppliers_id_customer_id_key" ON "suppliers"("id","customer_id"); CREATE INDEX "suppliers_customer_id_active_idx" ON "suppliers"("customer_id","active"); CREATE INDEX "suppliers_customer_id_country_idx" ON "suppliers"("customer_id","country");
CREATE UNIQUE INDEX "factories_id_customer_id_key" ON "factories"("id","customer_id"); CREATE INDEX "factories_customer_id_active_idx" ON "factories"("customer_id","active"); CREATE INDEX "factories_customer_id_supplier_id_idx" ON "factories"("customer_id","supplier_id");
CREATE UNIQUE INDEX "products_id_customer_id_key" ON "products"("id","customer_id"); CREATE UNIQUE INDEX "products_customer_id_sku_key" ON "products"("customer_id","sku"); CREATE INDEX "products_customer_id_active_idx" ON "products"("customer_id","active");
CREATE UNIQUE INDEX "materials_id_customer_id_key" ON "materials"("id","customer_id"); CREATE INDEX "materials_customer_id_active_idx" ON "materials"("customer_id","active");
CREATE UNIQUE INDEX "ports_port_code_key" ON "ports"("port_code"); CREATE INDEX "ports_active_country_idx" ON "ports"("active","country");
CREATE UNIQUE INDEX "routes_id_customer_id_key" ON "routes"("id","customer_id"); CREATE INDEX "routes_customer_id_active_idx" ON "routes"("customer_id","active");
CREATE INDEX "factory_products_customer_id_idx" ON "factory_products"("customer_id"); CREATE INDEX "product_materials_customer_id_idx" ON "product_materials"("customer_id"); CREATE INDEX "supplier_products_customer_id_idx" ON "supplier_products"("customer_id");
CREATE UNIQUE INDEX "route_ports_route_id_sequence_key" ON "route_ports"("route_id","sequence"); CREATE INDEX "route_ports_customer_id_idx" ON "route_ports"("customer_id"); CREATE INDEX "route_ports_port_id_idx" ON "route_ports"("port_id");
CREATE INDEX "route_suppliers_customer_id_idx" ON "route_suppliers"("customer_id"); CREATE INDEX "route_factories_customer_id_idx" ON "route_factories"("customer_id");

ALTER TABLE "suppliers" ADD CONSTRAINT "suppliers_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "factories" ADD CONSTRAINT "factories_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "factories" ADD CONSTRAINT "factories_supplier_id_customer_id_fkey" FOREIGN KEY ("supplier_id","customer_id") REFERENCES "suppliers"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "products" ADD CONSTRAINT "products_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
