ALTER TABLE "factory_products" ADD CONSTRAINT "factory_products_product_id_customer_id_fkey" FOREIGN KEY ("product_id","customer_id") REFERENCES "products"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "product_materials" ADD CONSTRAINT "product_materials_product_id_customer_id_fkey" FOREIGN KEY ("product_id","customer_id") REFERENCES "products"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "product_materials" ADD CONSTRAINT "product_materials_material_id_customer_id_fkey" FOREIGN KEY ("material_id","customer_id") REFERENCES "materials"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "supplier_products" ADD CONSTRAINT "supplier_products_supplier_id_customer_id_fkey" FOREIGN KEY ("supplier_id","customer_id") REFERENCES "suppliers"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "supplier_products" ADD CONSTRAINT "supplier_products_product_id_customer_id_fkey" FOREIGN KEY ("product_id","customer_id") REFERENCES "products"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_ports" ADD CONSTRAINT "route_ports_route_id_customer_id_fkey" FOREIGN KEY ("route_id","customer_id") REFERENCES "routes"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_ports" ADD CONSTRAINT "route_ports_port_id_fkey" FOREIGN KEY ("port_id") REFERENCES "ports"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_suppliers" ADD CONSTRAINT "route_suppliers_route_id_customer_id_fkey" FOREIGN KEY ("route_id","customer_id") REFERENCES "routes"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_suppliers" ADD CONSTRAINT "route_suppliers_supplier_id_customer_id_fkey" FOREIGN KEY ("supplier_id","customer_id") REFERENCES "suppliers"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_factories" ADD CONSTRAINT "route_factories_route_id_customer_id_fkey" FOREIGN KEY ("route_id","customer_id") REFERENCES "routes"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "route_factories" ADD CONSTRAINT "route_factories_factory_id_customer_id_fkey" FOREIGN KEY ("factory_id","customer_id") REFERENCES "factories"("id","customer_id") ON DELETE RESTRICT ON UPDATE CASCADE;
